use alloc::sync::Arc;
use zenpixels::{ColorContext, ColorOrigin, PixelDescriptor, PixelFormat, PixelSlice, PixelSliceMut};
use zenpixels_convert::{ConvertError, ConvertOptions, OutputPlan, output::{OutputMetadata, OutputProfile}};
use whereat::At;

impl OutputPlan {
    pub fn new(
        source_desc: PixelDescriptor,
        current: Option<Arc<ColorContext>>,
        origin: &ColorOrigin,
        target: OutputProfile,
        pixel_format: PixelFormat,
        options: &ConvertOptions,
        cms: Option<&dyn zenpixels_convert::cms::PluggableCms>,
    ) -> Result<Self, At<ConvertError>>;

    pub fn new_with_descriptor(
        source_desc: PixelDescriptor,
        current: Option<Arc<ColorContext>>,
        origin: &ColorOrigin,
        target: OutputProfile,
        output: PixelDescriptor,
        options: &ConvertOptions,
        cms: Option<&dyn zenpixels_convert::cms::PluggableCms>,
    ) -> Result<Self, At<ConvertError>>;

    pub fn new_preserving_samples(
        source_desc: PixelDescriptor,
        current: Option<Arc<ColorContext>>,
        origin: &ColorOrigin,
        target: OutputProfile,
        output: PixelDescriptor,
    ) -> Result<Self, At<ConvertError>>;

    pub fn output_descriptor(&self) -> PixelDescriptor;

    pub fn metadata(&self) -> &OutputMetadata;

    pub fn prepare(&mut self, max_width: u32) -> Result<(), At<ConvertError>>;

    pub fn borrow_rows<'a>(
        &self,
        source: PixelSlice<'a>,
    ) -> Result<Option<PixelSlice<'a>>, At<ConvertError>>;

    pub fn convert_rows<'a>(
        &mut self,
        source: PixelSlice<'_>,
        mut destination: PixelSliceMut<'a>,
    ) -> Result<PixelSliceMut<'a>, At<ConvertError>>;
}
